-- =====================================================================
-- Helper Academy — v70: 💔 pain. For each condition: its core (المحور), its own pain, what it does with other people's pain,
--   and how to protect yourself or help. Plus the word "Pain". Built by tools/characters/build_v70.py. Run AFTER v69.
-- =====================================================================
alter table public.conditions add column if not exists harm text check (harm in ('self','goal','pleasure','storm','cold','inside')),
  add column if not exists core text, add column if not exists core_ar text, add column if not exists own_pain text,
  add column if not exists others_pain text, add column if not exists others_pain_ar text, add column if not exists protect text;
update public.conditions set harm = 'self', core = 'the self-image (the ego)', core_ar = 'الأنا', own_pain = 'A fragile self-worth: criticism, being ignored or failing feels like humiliation, and the shame often turns into anger.', others_pain = '"I matter more than you." May hurt you for their own sake, or when their image is wounded. Hurting you is not the goal in itself.', others_pain_ar = 'أنا أهم منك؛ وقد أؤذيك من أجل نفسي أو إذا جرحتَ صورتي، وأذيتك ليست هدفًا بذاتها.', protect = 'Don''t feed the need for admiration or fight for the last word; keep calm, firm boundaries and judge by actions, not charm.' where key = 'narcissistic';
update public.conditions set harm = 'self', core = 'admiration', core_ar = 'الإعجاب', own_pain = 'Needs constant admiration; without it, feels empty or angry.', others_pain = 'Hurts you when you don''t admire them enough or when you shine more.', others_pain_ar = null, protect = 'Stay polite but don''t compete for attention; keep your achievements for people who are glad for you.' where key = 'grandiose_narcissism';
update public.conditions set harm = 'self', core = 'hidden shame', core_ar = 'الخزي المستتر', own_pain = 'Secret shame and the feeling of not being appreciated; deeply wounded by small criticism.', others_pain = 'Hurts you quietly: sulking, silent treatment, envy and holding grudges.', others_pain_ar = null, protect = 'Be kind but don''t take responsibility for their moods; say things directly and calmly.' where key = 'vulnerable_narcissism';
update public.conditions set harm = 'self', core = 'the ego, with cruelty', core_ar = 'الأنا مع القسوة', own_pain = 'Rage when the image is threatened.', others_pain = 'May hurt you to dominate, punish or enjoy it, without guilt.', others_pain_ar = null, protect = 'Protection first: keep distance, keep records, get help from authorities if needed.' where key = 'malignant_narcissism';
update public.conditions set harm = 'goal', core = 'the goal', core_ar = 'الغاية', own_pain = 'Feels little fear or guilt; boredom and the need for excitement push them on.', others_pain = '"I want something." Your pain is not a strong enough moral or emotional brake. May hurt you if you are in the way, or if hurting you helps them.', others_pain_ar = 'أريد شيئًا؛ وأذيتك لا تشكّل لي حاجزًا أخلاقيًا أو عاطفيًا كافيًا، قد أؤذيك إذا كنتَ عقبة أو إذا كان في أذيتك منفعة لي.', protect = 'Don''t count on pity or guilt to stop them; keep distance, protect what matters, and involve people in authority.' where key = 'psychopathy';
update public.conditions set harm = 'pleasure', core = 'pleasure', core_ar = 'المتعة', own_pain = 'Not driven by a need from you: the suffering itself is the reward.', others_pain = '"Your suffering itself gives me pleasure."', others_pain_ar = 'معاناتك نفسها تعطيني متعة.', protect = 'Don''t show them your pain as a game; leave, protect yourself, and tell people who can stop them.' where key = 'sadism';
update public.conditions set harm = 'goal', core = 'my goal', core_ar = 'غايتي', own_pain = 'Trusts no one, sees people as tools, so must always stay on guard.', others_pain = '"I have a goal; I may use you to reach it, break my promise or betray you. I understand your feelings so I know how to influence you."', others_pain_ar = 'لدي غاية؛ قد أستخدمك للوصول إليها، وقد أنكث عهدي أو أغدر بك. أفهم مشاعرك لأعرف كيف أؤثر فيك وأحقق مرادي.', protect = 'Watch actions, not words; put agreements in writing; don''t share secrets that can be used against you.' where key = 'machiavellianism';
update public.conditions set harm = 'goal', core = 'what I want, now', core_ar = 'رغبتي الآن', own_pain = 'Restlessness, anger and trouble with rules and people, but little guilt.', others_pain = 'Your pain doesn''t stop them: may hurt you to get something, or in anger, and feel little remorse.', others_pain_ar = null, protect = 'Clear limits and consequences; your safety comes first; involve the law when needed.' where key = 'antisocial_pd';
update public.conditions set harm = 'goal', core = 'self-interest', core_ar = 'المصلحة الذاتية', own_pain = 'Callousness: little feeling for others.', others_pain = 'Uses, charms and discards people for their own gain.', others_pain_ar = null, protect = 'Judge by patterns over time, not by charm.' where key = 'dark_triad';
update public.conditions set harm = 'pleasure', core = 'self-interest and cruelty', core_ar = 'المصلحة والقسوة', own_pain = 'Callousness plus enjoyment of others'' pain.', others_pain = 'May hurt you for gain, and sometimes simply because it is enjoyable to them.', others_pain_ar = null, protect = 'Distance and protection; never handle it alone.' where key = 'dark_tetrad';
update public.conditions set harm = 'storm', core = 'fear of being abandoned', core_ar = 'الخوف من الهجر', own_pain = 'Very intense emotional pain, emptiness and terror of being left; feelings that swing fast.', others_pain = 'Doesn''t want to hurt you. When they feel abandoned, the pain explodes and you may get hurt in the storm, and afterwards they often feel deep shame.', others_pain_ar = null, protect = 'Stay calm and consistent, name their feelings, and keep clear, kind boundaries; DBT therapy helps.' where key = 'bpd';
update public.conditions set harm = 'storm', core = 'attention', core_ar = 'لفت الانتباه', own_pain = 'Feeling invisible or unimportant hurts deeply.', others_pain = 'Not trying to hurt; may hurt through drama, exaggeration or using others to be noticed.', others_pain_ar = null, protect = 'Give attention to calm, real moments, not to the drama.' where key = 'histrionic_pd';
update public.conditions set harm = 'storm', core = 'protection from betrayal', core_ar = 'الحماية من الغدر', own_pain = 'Lives in constant fear of being tricked or betrayed, which makes them lonely.', others_pain = 'Hurts you because they believe you are about to hurt them: attacks first.', others_pain_ar = null, protect = 'Be transparent, predictable and patient; don''t argue with the suspicion, show by actions.' where key = 'paranoid_pd';
update public.conditions set harm = 'cold', core = 'distance', core_ar = 'المسافة', own_pain = 'Often feels little; sometimes a loneliness they don''t show.', others_pain = 'No wish to hurt; may hurt you by coldness or absence.', others_pain_ar = null, protect = 'Respect their space; don''t read distance as hate.' where key = 'schizoid_pd';
update public.conditions set harm = 'inside', core = 'an unusual inner world', core_ar = 'عالم داخلي غريب', own_pain = 'Social anxiety and feeling different from everyone.', others_pain = 'Rarely hurts others.', others_pain_ar = null, protect = 'Patience and acceptance.' where key = 'schizotypal_pd';
update public.conditions set harm = 'inside', core = 'avoiding rejection', core_ar = 'تجنّب الرفض', own_pain = 'Deep fear of rejection, feeling inferior, and loneliness.', others_pain = 'Doesn''t want to hurt; may hurt you by disappearing or cancelling.', others_pain_ar = null, protect = 'Gentle, patient invitations; never mock.' where key = 'avoidant_pd';
update public.conditions set harm = 'inside', core = 'not being left alone', core_ar = 'ألّا أُترك وحيدًا', own_pain = 'Fear of being alone and unable to cope.', others_pain = 'Rarely hurts others; may wear them out by needing them all the time.', others_pain_ar = null, protect = 'Encourage small decisions on their own; be supportive but don''t decide everything for them.' where key = 'dependent_pd';
update public.conditions set harm = 'storm', core = 'order and control', core_ar = 'النظام والسيطرة', own_pain = 'Stress and the feeling that nothing is ever good enough.', others_pain = 'Hurts with criticism, rigid rules and control.', others_pain_ar = null, protect = 'Agree on what "good enough" means; protect your own way of doing things.' where key = 'ocpd';
update public.conditions set harm = 'self', core = 'staying on top', core_ar = 'البقاء في القمة', own_pain = 'Often insecurity hidden behind control.', others_pain = 'Hurts with put-downs, guilt and manipulation, usually without admitting it.', others_pain_ar = null, protect = 'Clear boundaries, less contact, and talk to someone you trust.' where key = 'toxic';
update public.conditions set harm = 'self', core = 'power and status in the group', core_ar = 'القوة والمكانة', own_pain = 'Often their own insecurity, or being hurt somewhere else.', others_pain = 'Hurts others to feel strong or to look strong in front of the group.', others_pain_ar = null, protect = 'Tell a trusted adult; bystanders speak up together; don''t fight alone.' where key = 'bullying';
update public.conditions set harm = 'self', core = 'the other person''s advantage', core_ar = 'ميزة الآخر', own_pain = 'The pain of feeling smaller than someone.', others_pain = 'Your loss eases their pain of feeling smaller, even when they gain nothing.', others_pain_ar = null, protect = 'Don''t show off to them; build your own circle; for the envious one: gratitude and building yourself.' where key = 'malicious_envy';
update public.conditions set harm = 'storm', core = 'the relationship', core_ar = 'العلاقة', own_pain = 'Fear of losing someone they love.', others_pain = 'May hurt by checking, accusing or controlling, out of fear.', others_pain_ar = null, protect = 'Talk openly, reassure honestly, and set limits on control.' where key = 'jealousy';
update public.conditions set harm = 'goal', core = 'the role and the situation', core_ar = 'الدور والموقف', own_pain = 'Pressure to obey and fit the role.', others_pain = 'Ordinary people hurt others when a role, power or a group pushes them and nobody checks.', others_pain_ar = null, protect = 'Rules for everyone, someone checking, and the courage to say no.' where key = 'lucifer_effect';
update public.conditions set harm = 'goal', core = 'control over your reality', core_ar = 'السيطرة على إدراكك', own_pain = null, others_pain = 'Makes you doubt your memory and feelings so you depend on their version.', others_pain_ar = null, protect = 'Write things down and check with people you trust.' where key = 'gaslighting';
update public.conditions set harm = 'self', core = 'my image against yours', core_ar = 'صورتي مقابل صورتك', own_pain = null, others_pain = 'Hurts your name quietly, keeping their hands clean.', others_pain_ar = null, protect = 'Ask directly, "What do you mean?", and let your actions speak.' where key = 'silent_assassination';
update public.conditions set harm = 'self', core = 'control of the group', core_ar = 'السيطرة على الجماعة', own_pain = null, others_pain = 'Hurts by making you invisible; it hurts as much as being hit.', others_pain_ar = null, protect = 'Invite the one left out; one friend makes all the difference.' where key = 'social_exclusion';
update public.conditions set harm = 'inside', core = 'calming unbearable worry', core_ar = 'تهدئة القلق', own_pain = 'Torment from thoughts that won''t stop, and exhaustion from the rituals.', others_pain = 'Not about hurting anyone.', others_pain_ar = null, protect = 'Patience; don''t mock the rituals; doctors and therapists can treat it.' where key = 'ocd';
update public.conditions set harm = 'inside', core = 'staying safe', core_ar = 'النجاة والأمان', own_pain = 'Memories, nightmares and fear that keep coming back.', others_pain = 'Not about hurting anyone; may snap when frightened.', others_pain_ar = null, protect = 'Safety, patience and professional help.' where key = 'ptsd';
update public.conditions set harm = 'inside', core = 'a different way of experiencing the world', core_ar = 'طريقة مختلفة في الإدراك', own_pain = 'Sensory overload, sudden changes and being misunderstood can hurt a lot.', others_pain = 'Not about hurting anyone.', others_pain_ar = null, protect = 'Understanding, routines and quiet spaces.' where key = 'autism';
update public.conditions set harm = 'inside', core = 'staying close', core_ar = 'البقاء قريبًا', own_pain = 'Fear of being left or loved less.', others_pain = 'Doesn''t want to hurt; may tire others with checking and needing reassurance.', others_pain_ar = null, protect = 'Reliable love and learning to calm yourself.' where key = 'anxious_attachment';
update public.conditions set harm = 'cold', core = 'staying safe from closeness', core_ar = 'الأمان من القرب', own_pain = 'Hidden fear of being hurt or depending on anyone.', others_pain = 'May hurt you by coldness and distance.', others_pain_ar = null, protect = 'Patience; small, safe steps of sharing.' where key = 'avoidant_attachment';
update public.conditions set harm = 'inside', core = 'not being enough', core_ar = 'ألّا أكون كافيًا', own_pain = 'Feeling worthless and afraid to try.', others_pain = 'Rarely hurts others.', others_pain_ar = null, protect = 'Small wins and kind people.' where key = 'low_self_esteem';
update public.conditions set harm = 'inside', core = 'hiding sadness', core_ar = 'إخفاء الحزن', own_pain = 'Sadness or loneliness hidden behind jokes.', others_pain = 'Rarely hurts others, unless the jokes get unkind.', others_pain_ar = null, protect = 'Ask, "How are you, really?" and listen.' where key = 'funny_mask';
insert into public.words (lang, headword, sense, meaning, example, translation, syllables, pronunciation, emoji, audio_url, author, tags, owner_id)
select 'en', 'Pain', '', 'A feeling that hurts, in the body or in the heart. People with different personalities feel their own pain differently, and treat the pain they cause others differently too (see 💔 Pain in Characters).',
  'The [pain] in her knee went away, but the pain of losing the match stayed longer.', 'الألم', '', '', '💔', '', '', array['Feelings & moods','Health & body','Naming: things & places']::text[],
  (select p.id from public.profiles p join auth.users u on u.id = p.id where u.email = 'albarq2000@hotmail.com')
where not exists (select 1 from public.words w where w.lang = 'en' and lower(w.headword) = 'pain' and w.sense = '');
update public.words set meaning = 'A feeling that hurts, in the body or in the heart. People with different personalities feel their own pain differently, and treat the pain they cause others differently too (see 💔 Pain in Characters).'
  where lang = 'en' and lower(headword) = 'pain' and sense = '';
select count(*) filter (where core is not null) as with_core, count(*) filter (where harm in ('self','goal','pleasure')) as hurt_on_purpose from public.conditions;
